import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Técnicas y especialización","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/characters/techniques-and-specialization.md","filePath":"es/game-design/characters/techniques-and-specialization.md"}'),o={name:"es/game-design/characters/techniques-and-specialization.md"};function r(t,e,c,d,l,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="techniques-specialization" tabindex="-1">Técnicas y especialización <a class="header-anchor" href="#techniques-specialization" aria-label="Enlace permanente a &quot;Técnicas y especialización&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las preguntas abiertas permanecen Sin resolver. Las decisiones citadas con estado Aceptado conservan su alcance existente. <strong>Implementación/disponibilidad:</strong> no hay cambios en gameplay ni en configuración de ejecución; no se ha establecido que este rediseño esté activo. <strong>Verificación:</strong> revisión documental, no prueba de juego; aquí no se establece la disponibilidad actual. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/characters/techniques.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/characters/progression.html">Progresión del personaje</a></p><h2 id="skill-learned-knowledge-and-identity" tabindex="-1">Habilidad, conocimiento aprendido e identidad <a class="header-anchor" href="#skill-learned-knowledge-and-identity" aria-label="Enlace permanente a &quot;Habilidad, conocimiento aprendido e identidad&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concepto</th><th>Significado</th><th>Ejemplos</th></tr></thead><tbody><tr><td>Habilidad</td><td>Capacidad general subyacente</td><td>Carpentry, Blacksmithing, Tinkering</td></tr><tr><td>Técnica / Escuela</td><td>Conocimiento concreto aprendido dentro de habilidades o entre ellas</td><td>Bowmaking, Advanced Tillering, Bladesmithing, Armorsmithing, Luthiery, Distillation, Toxicology</td></tr><tr><td>Camino profesional</td><td>Identidad práctica especializada a partir de habilidades, técnicas, experiencia y reputación</td><td>Maestro fabricante de arcos</td></tr><tr><td>Identidad avanzada</td><td>Aquello por lo que un personaje concreto se hace conocido en el mundo</td><td>Un fabricante de arcos famoso por sus arcos de guerra muy duraderos</td></tr></tbody></table><p>Esto centraliza la jerarquía del Batch 01 para los personajes en general. Un carpintero competente puede desconocer Bowmaking; un herrero técnicamente hábil puede desconocer una escuela rara de forja de hojas. Esta separación es intencional.</p><p><strong>La habilidad determina la capacidad; el conocimiento determina las posibilidades/información; la maestría del jugador determina el rendimiento.</strong> El <a href="/Syrolands-Public/es/game-design/characters/progression.html#character-skill-knowledge-and-player-mastery">marco de progresión</a> define el principio de tres ejes y sus ejemplos. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#character-journals-and-discovery">Sistema de profesiones</a> define diarios artesanales, descubrimientos observados y restricciones al compartir conocimiento.</p><h2 id="learning-techniques-and-schools" tabindex="-1">Aprender técnicas y escuelas <a class="header-anchor" href="#learning-techniques-and-schools" aria-label="Enlace permanente a &quot;Aprender técnicas y escuelas&quot;">​</a></h2><p>Entre las posibles fuentes hay maestros NPC, academias, gremios, manuscritos, exploración, misiones/desafíos, competiciones, reputación, enseñanza de jugadores e ingeniería inversa cuando corresponda. Una posible jerarquía es <strong>Fundamentos → Técnicas avanzadas → Técnicas maestras</strong>, no un árbol de ventajas aprobado ni una escala de desbloqueos automáticos por habilidad.</p><p>Las técnicas son procedimientos concretos y comprensión, no nodos abstractos de bonificación. No hacer que todas sean mutuamente excluyentes por defecto. La especialización debería surgir principalmente de invertir el límite de habilidades, tiempo, adquisición de conocimiento, práctica y reputación, en lugar de bloqueos arbitrarios por clase.</p><p>Poseer una técnica y poder ejecutarla bien son cosas distintas. La habilidad alta no concede todas las técnicas por sí sola, y copiar instrucciones no elimina los requisitos de capacidad del personaje. <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Bowmaking/Fletching</a> sigue dentro de Carpentry/Archery, pendiente de conciliar el listado heredado de habilidades; esta página no elimina ninguna habilidad.</p><h2 id="persistence-and-information-boundary" tabindex="-1">Persistencia y límite de información <a class="header-anchor" href="#persistence-and-information-boundary" aria-label="Enlace permanente a &quot;Persistencia y límite de información&quot;">​</a></h2><p>El conocimiento persistente del personaje es una dirección de diseño, no un esquema seleccionado. La intención de enseñar es una solicitud del cliente; el conocimiento aprendido real y la elegibilidad para ejecutarlo son decisiones del servidor; el conocimiento sincronizado se limita a la información cuya divulgación está aprobada; el diario/interfaz es presentación. El trabajo técnico posterior debe respetar las restricciones de autoridad y persistencia.</p><p>Las descripciones públicas de capacidad pueden explicar la progresión sin revelar cada escuela, receta o interacción oculta. Los nombres de técnicas de este lote son ejemplos, no un catálogo completo ni una ruta de adquisición prometida.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Reglas exactas de maestros/enseñanza entre jugadores; requisitos y reconocimiento de fundamentos; si determinadas escuelas entran en conflicto; costes y requisitos de reputación; persistencia, propiedad/custodia y transferencia del conocimiento; redistribución/olvido; descubrimiento frente a conocimiento enseñado; cómo revela posibilidades la interfaz de capacidades sin estropear secretos. No se selecciona exclusividad universal, límite de espacios de técnicas ni regla de pérdida de conocimiento.</p><h2 id="combat-and-spell-fluency-—-batch-05" tabindex="-1">Fluidez de combate y hechizos — Batch 05 <a class="header-anchor" href="#combat-and-spell-fluency-—-batch-05" aria-label="Enlace permanente a &quot;Fluidez de combate y hechizos — Batch 05&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity compartida</a> separa la adquisición permanente de técnicas de la fluidez Learned / Practiced / Mastered y de las opciones preparadas. El deterioro ordinario de mantenimiento nunca convierte una técnica conocida en Unknown. Esto aclara el deterioro en combate/hechizos sin cerrar redistribución/olvido voluntarios ni todas las políticas de conocimiento profesional. Los <a href="/Syrolands-Public/es/game-design/combat/actions.html">Special Attacks</a> usan la misma filosofía de aprendizaje en el mundo.</p>',18)])])}const h=a(o,[["render",r]]);export{m as __pageData,h as default};
